        "net_notes_onewin": "1. Trong tài khoản 1win, vào PR Tools - Links. Ở cột Actions, nhấp vào biểu tượng liên kết.\n\n2. Trong Postback Url, thay status=[REPLACE] bằng:\n\nstatus=lead - cho Đăng ký\n\nstatus=sale - cho Nạp tiền lần đầu\n\nstatus=sale&tid={event_id} - cho Nạp tiền\n\ncurrency=[ISO] - thay bằng mã tiền tệ theo định dạng ISO (ví dụ: currency=usd)",
