        "helpTitle": "Quyền truy cập hoạt động thế nào",
        "permissionsLegend": "\"Toàn quyền\": xem và thay đổi mọi thứ trong mục. \"Chỉ đọc\": xem mọi thứ nhưng không thay đổi được gì. Các tùy chọn \"+ Đã chọn\" chỉ áp dụng cho nhóm và mục đã đánh dấu, cùng những gì người dùng tự tạo. \"Không có quyền truy cập\": ẩn mục này.",
        "helpRolesTitle": "Hai vai trò",
        "helpRolesText": "Quản trị viên thấy và làm được mọi thứ; quyền không áp dụng cho quản trị viên. Người dùng chỉ có những gì được cấp trong Quyền — biểu tượng khiên ở dòng người dùng.",
        "helpLevelsTitle": "Mức truy cập của một mục",
        "helpLevelsText": "\"Toàn quyền\": xem và thay đổi mọi thứ. \"Chỉ đọc\": xem mọi thứ nhưng không thể tạo, thay đổi hay xóa. \"Không có quyền truy cập\": ẩn mục khỏi menu và chặn truy cập trên máy chủ.",
        "helpSelectedTitle": "\"Toàn quyền + Đã chọn\" và \"Chỉ đọc + Đã chọn\"",
        "helpSelectedText": "Áp dụng cho chiến dịch, offer, landing và tên miền. Người dùng chỉ thấy các nhóm đã đánh dấu, các mục riêng lẻ đã đánh dấu và những gì họ tự tạo. Mọi thứ khác coi như không tồn tại với họ: không có trong danh sách và không mở được bằng liên kết trực tiếp. Ở chế độ \"Chỉ đọc\", không thể thay đổi gì, kể cả mục do chính họ tạo.",
        "helpGroupsTitle": "Nhóm luôn cập nhật",
        "helpGroupsText": "Khi cấp một nhóm, người dùng thấy mọi thứ đang có trong nhóm và mọi thứ được thêm vào sau này. Đưa một mục ra khỏi nhóm thì mục đó biến mất với họ. Có thể cấp riêng một mục trong nhóm của người khác mà không cần mở cả nhóm.",
        "helpLimitsTitle": "Những việc người dùng \"Được chọn\" không thể làm",
        "helpLimitsText": "Tạo, đổi tên hoặc xóa nhóm; chuyển mục không do mình tạo sang nhóm khác; thêm vào chiến dịch của mình offer, landing hoặc tên miền chưa được cấp quyền (những gì quản trị viên đã gắn sẵn vẫn giữ nguyên). Trên trang Tên miền, không dùng được nhà đăng ký, nhập tên miền và kiểm tra toàn bộ tên miền.",
        "helpStatsTitle": "Thống kê",
        "helpStatsText": "Bảng điều khiển, báo cáo, chuyển đổi và nhật ký chỉ hiển thị dữ liệu của các chiến dịch mà người dùng có quyền truy cập.",
        "helpFinanceTitle": "Dữ liệu tài chính",
        "helpFinanceText": "Các ô đánh dấu ở cuối cửa sổ phân quyền sẽ ẩn chi phí, doanh thu và payout trong mọi bảng và báo cáo — máy chủ hoàn toàn không gửi các con số này.",
        "helpTemplatesTitle": "Mẫu vai trò",
        "helpTemplatesText": "Bộ quyền ban đầu để thiết lập nhanh cho người dùng mới. Media Buyer — toàn quyền các mục traffic, tên miền và nhật ký chỉ đọc, xem được tài chính. Creative Designer — toàn quyền landing và media, các mục khác bị khóa, ẩn tài chính. Developer — toàn quyền landing, push và nhật ký, các mục khác chỉ đọc, ẩn tài chính. Custom — không điền sẵn gì. Không thể lưu preset riêng: bộ quyền chỉ áp dụng một lần rồi gắn với người dùng đó, muốn sửa hãy dùng biểu tượng khiên.",
        "helpOffboardTitle": "Có người rời nhóm",
        "helpOffboardText": "Xóa tài khoản của họ: họ sẽ bị đăng xuất khỏi bảng điều khiển ngay ở thao tác tiếp theo và API key của họ ngừng hoạt động. Thay đổi quyền cũng có hiệu lực ngay, không cần đăng nhập lại.",
        "mcpTitle": "Kết nối trợ lý AI (MCP)",
        "mcpDesc": "Tạo key ở trên, rồi dán đoạn này vào cấu hình Claude Desktop. Thay đường dẫn bằng đường dẫn tuyệt đối tới mcp/src/index.js và thay ORBITRA_API_KEY bằng key của bạn. Hướng dẫn đầy đủ: mcp/README.md.",
        "mcpCopyConfig": "Sao chép cấu hình",
