    "help": {
        "campaignBannerTitle": "Chiến dịch là gì?",
        "campaignBanner": "Chiến dịch là thực thể chính trong tracker. Chiến dịch nhận traffic qua một URL duy nhất, rồi định tuyến qua các luồng (quy tắc) tới offer và landing. Mỗi chiến dịch có thể có nhiều luồng với quy tắc nhắm mục tiêu, bộ lọc geo và thử nghiệm A/B khác nhau.",
        "offerBannerTitle": "Offer là gì?",
        "offerBanner": "Offer là đích đến cuối cùng của traffic — thường là trang của nhà quảng cáo. Offer có thể là URL chuyển hướng, iframe nhúng hoặc trang lưu trữ cục bộ. Mỗi offer gắn với một mạng affiliate và theo dõi chuyển đổi cùng doanh thu.",
        "landingBannerTitle": "Landing là gì?",
        "landingBanner": "Landing (prelander) là trang trung gian hiển thị trước offer, giúp làm nóng khách và tăng chuyển đổi. Bạn có thể A/B test nhiều landing trong một luồng. Landing có thể là liên kết ngoài (URL) hoặc tải lên dưới dạng tệp ZIP.",
        "trafficSourceBannerTitle": "Nguồn traffic là gì?",
        "trafficSourceBanner": "Nguồn traffic cho biết traffic đến từ đâu — mạng quảng cáo, mạng xã hội, v.v. Khi thiết lập nguồn, bạn có thể truyền tham số (sub ID, chi phí, từ khóa) và theo dõi ROI theo từng nguồn. Dùng mẫu cho các mạng phổ biến.",
        "affiliateNetworkBannerTitle": "Mạng affiliate là gì?",
        "affiliateNetworkBanner": "Mạng affiliate là đối tác cung cấp offer. Khi thêm mạng, bạn có thể cấu hình URL postback để tự động theo dõi chuyển đổi. Mạng sẽ gửi postback khi người dùng hoàn thành một hành động (sale, lead, v.v.).",
        "domainBannerTitle": "Tên miền tracking",
        "domainBanner": "Tên miền tracking giúp ẩn URL tracker và làm liên kết trông tự nhiên hơn. Trỏ bản ghi A của tên miền về IP máy chủ, thêm tên miền vào đây rồi gán cho chiến dịch. Bật HTTPS và noindex để tăng bảo mật và bảo vệ SEO.",
        "postbackBannerTitle": "Postback hoạt động thế nào?",
        "postbackBanner": "Postback (S2S Postback) là yêu cầu HTTP mà mạng affiliate gửi tới tracker khi có chuyển đổi. URL chứa ID click (subid), trạng thái và payout. Tracker đối chiếu với click gốc rồi ghi nhận chuyển đổi.",
        "postbackMacros": "Macro khả dụng: {subid} — ID click, {status} — trạng thái chuyển đổi, {payout} — số tiền, {tid} — ID giao dịch, {currency} — mã tiền tệ.",
        "integrationsBannerTitle": "Tích hợp thế nào?",
        "integrationsBanner": "Chọn cách tích hợp phù hợp với hạ tầng kỹ thuật của bạn. Tracking Client (PHP) có đầy đủ tính năng phía máy chủ (cloak, lọc bot). Tracking Client (JS) dễ cài đặt hơn. Tracking Pixel phù hợp để theo dõi lượt hiển thị và chuyển đổi ở mức cơ bản.",
        "conversionsBannerTitle": "Trạng thái chuyển đổi",
        "conversionsBanner": "Mỗi chuyển đổi có một trạng thái: lead — lead mới, sale — đơn hàng đã xác nhận, rejected — bị nhà quảng cáo từ chối, deposit — nạp tiền lần đầu (gambling), registration — người dùng đăng ký. Bạn có thể cấu hình trạng thái tùy chỉnh trong Cài đặt.",
        "trendsBannerTitle": "Cách sử dụng phân tích",
        "trendsBanner": "Chọn chỉ số cần hiển thị, khoảng ngày và cách nhóm. Dùng bộ lọc để thu hẹp dữ liệu theo bất kỳ trường nào của click. Biểu đồ và bảng cập nhật theo thời gian thực. So sánh các chỉ số để tìm quy luật — ví dụ: click nhiều nhưng CR thấp có thể cho thấy landing đang có vấn đề.",
        "aliasTooltip": "Mã định danh ngắn, duy nhất cho URL chiến dịch. Tự động tạo nhưng có thể thay đổi. Dùng trong liên kết tracking.",
        "costModelTooltip": "CPC — trả theo click. CPA — trả theo chuyển đổi. CPM — trả theo 1000 lượt hiển thị. RevShare — phần trăm doanh thu. CPuC — theo click duy nhất. CPS — theo đơn hàng.",
        "uniquenessTooltip": "Cách xác định khách duy nhất. IP — chỉ theo địa chỉ IP. IP+UA — theo IP và User-Agent (chính xác hơn). Cookies — cookie trình duyệt (chính xác nhất nhưng có thể bị chặn).",
        "rotationTooltip": "Trọng số — chia traffic theo tỷ lệ trọng số. Vị trí — gửi toàn bộ traffic tới luồng đang hoạt động đầu tiên, các luồng còn lại làm dự phòng.",
        "redirectTypeTooltip": "Redirect — chuyển hướng 302 tiêu chuẩn (nhanh, phổ biến). iFrame — tải trong khung ẩn (phù hợp cho cloak). Local — trả về trang lưu trữ cục bộ (tốt nhất cho phễu phức tạp).",
        "offerPostbackTooltip": "URL mà mạng affiliate gửi khi có chuyển đổi. Phải chứa macro ID click (thường là {subid} hoặc {clickid}). Đặt URL này trong bảng điều khiển của mạng affiliate.",
        "postbackKeyTooltip": "Khóa bảo mật thêm vào URL postback, giúp chặn postback trái phép từ bên thứ ba. Hãy đổi khóa nếu bị lộ.",
        "postbackAliasesTooltip": "Ánh xạ tên tham số. Nếu mạng gửi 'clickid' thay vì 'subid', hãy thêm 'clickid' làm alias. Tracker sẽ chấp nhận cả hai tên tham số.",
        "indexCampaignTooltip": "Chiến dịch hiển thị khi có người truy cập tên miền gốc (ví dụ: yourdomain.com). Nếu bỏ trống, khách sẽ thấy trang trống.",
        "httpsTooltip": "Tự động chuyển hướng mọi yêu cầu HTTP sang HTTPS. Nên bật để bảo mật. Hãy đảm bảo đã cấu hình chứng chỉ SSL.",
        "streamSchemaTooltip": "Chọn offer và landing sẽ hiển thị cho khách. Thêm nhiều mục và đặt trọng số để chạy A/B test. Tổng trọng số hiển thị ở phía trên.",
        "streamFilterTooltip": "Đặt điều kiện để kích hoạt luồng này: theo quốc gia, thiết bị, hệ điều hành, trình duyệt, ngôn ngữ, v.v. Traffic không khớp luồng nào sẽ chuyển tới luồng mặc định (catch-all).",
        "dismissAll": "Đã hiểu",
        "showHelp": "Hiện mẹo"
    },
